@@ -23516,2 +23518,11 @@
-    __ vector_count_trailing_zeros_evex_popc(bt, $dst$$XMMRegister, $src$$XMMRegister,
-                                             $xtmp$$XMMRegister, vlen_enc);
+    // ctz(x) = popcnt((x - 1) & ~x). See "Hacker's Delight" by Henry Warren.
+    // Targets with AVX512_VPOPCNTDQ or AVX512_BITALG have a direct vpopcnt.
+    __ vpxor($xtmp$$XMMRegister, $xtmp$$XMMRegister, $xtmp$$XMMRegister, vlen_enc);
+    // xtmp = -1
+    __ vpternlogd($xtmp$$XMMRegister, 0xff, $xtmp$$XMMRegister, $xtmp$$XMMRegister, vlen_enc);
+    // xtmp = xtmp + src
+    __ vpadd(bt, $xtmp$$XMMRegister, $xtmp$$XMMRegister, $src$$XMMRegister, vlen_enc);
+    // xtmp = xtmp & ~src
+    __ vpandn($xtmp$$XMMRegister, $src$$XMMRegister, $xtmp$$XMMRegister, vlen_enc);
+    // dst = popcount(xtmp)
+    __ vector_popcount_integral_evex(bt, $dst$$XMMRegister, $xtmp$$XMMRegister, k0, true, vlen_enc);
